package shilploka.world.chunk;

/**
 * WHY:
 * Represents a vertical 16x320x16 column of the world at chunk coordinates (cx, cz).
 * Managing chunks as vertical columns standardizes height boundaries, surface heightmaps,
 * and chunk streaming mechanics.
 *
 * WHAT:
 * Contains twenty 16³ ChunkSection objects spanning Y=0 to Y=319. Provides world-coordinate
 * to section-coordinate translation, dirty tracking for re-meshing, and block getters/setters.
 *
 * USED FOR:
 * Managed by ChunkManager in a spatial hash map and generated by WorldGenerator.
 *
 * WHERE NEXT:
 * Individual sections inside this column are passed to GreedyMesher for geometry generation.
 */
public class ChunkColumn {

    public static final int CHUNK_WIDTH = 16;
    public static final int CHUNK_HEIGHT = 320;
    public static final int SECTION_COUNT = CHUNK_HEIGHT / ChunkSection.SECTION_SIZE; // 20 sections

    private final int chunkX;
    private final int chunkZ;
    private final ChunkSection[] sections;
    private boolean dirty = true;

    /**
     * WHY:
     * Initializes a chunk column at the specified chunk grid coordinates.
     *
     * WHAT:
     * Instantiates 20 ChunkSection objects spanning sections 0 through 19.
     */
    public ChunkColumn(int chunkX, int chunkZ) {
        this.chunkX = chunkX;
        this.chunkZ = chunkZ;
        this.sections = new ChunkSection[SECTION_COUNT];

        for (int sy = 0; sy < SECTION_COUNT; sy++) {
            this.sections[sy] = new ChunkSection(sy);
        }
    }

    /**
     * WHY:
     * Retrieves the block ID at local (X, Z) and absolute vertical world Y coordinates.
     *
     * WHAT:
     * Validates bounds (0 <= Y < 320), routes query to appropriate section (worldY >> 4).
     */
    public int getBlock(int localX, int worldY, int localZ) {
        if (worldY < 0 || worldY >= CHUNK_HEIGHT || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return 0; // Air outside bounds
        }

        int sectionY = worldY >> 4;
        int localY = worldY & 15;
        return this.sections[sectionY].getBlock(localX, localY, localZ);
    }

    /**
     * WHY:
     * Sets the block state at local (X, Z) and absolute vertical world Y coordinates.
     *
     * WHAT:
     * Sets the block in the corresponding section and marks this chunk column as dirty.
     */
    public void setBlock(int localX, int worldY, int localZ, int blockId) {
        if (worldY < 0 || worldY >= CHUNK_HEIGHT || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return;
        }

        int sectionY = worldY >> 4;
        int localY = worldY & 15;
        this.sections[sectionY].setBlock(localX, localY, localZ, blockId);
        this.dirty = true;
    }

    /**
     * WHY:
     * Fast retrieval of 4-bit Sky Light level (0-15) from section storage.
     */
    public int getSkyLight(int localX, int worldY, int localZ) {
        if (worldY < 0 || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return 0;
        }
        if (worldY >= CHUNK_HEIGHT) {
            return 15; // Unbounded celestial sky
        }
        return this.sections[worldY >> 4].getSkyLight(localX, worldY & 15, localZ);
    }

    /**
     * Sets 4-bit Sky Light level (0-15) into section storage.
     */
    public void setSkyLight(int localX, int worldY, int localZ, int value) {
        if (worldY < 0 || worldY >= CHUNK_HEIGHT || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return;
        }
        this.sections[worldY >> 4].setSkyLight(localX, worldY & 15, localZ, value);
        this.dirty = true;
    }

    /**
     * WHY:
     * Fast retrieval of 4-bit Block Light level (0-15) from section storage.
     */
    public int getBlockLight(int localX, int worldY, int localZ) {
        if (worldY < 0 || worldY >= CHUNK_HEIGHT || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return 0;
        }
        return this.sections[worldY >> 4].getBlockLight(localX, worldY & 15, localZ);
    }

    /**
     * Sets 4-bit Block Light level (0-15) into section storage.
     */
    public void setBlockLight(int localX, int worldY, int localZ, int value) {
        if (worldY < 0 || worldY >= CHUNK_HEIGHT || localX < 0 || localX >= 16 || localZ < 0 || localZ >= 16) {
            return;
        }
        this.sections[worldY >> 4].setBlockLight(localX, worldY & 15, localZ, value);
        this.dirty = true;
    }

    /**
     * WHY:
     * Retrieves an individual 16³ section by section index (0-19).
     */
    public ChunkSection getSection(int sectionY) {
        if (sectionY < 0 || sectionY >= SECTION_COUNT) return null;
        return this.sections[sectionY];
    }

    /**
     * Sets an individual 16³ section by section index (used during chunk deserialization).
     */
    public void setSection(int sectionY, ChunkSection section) {
        if (sectionY >= 0 && sectionY < SECTION_COUNT) {
            this.sections[sectionY] = section;
            this.dirty = true;
        }
    }

    /**
     * WHY:
     * Checks if this chunk column has pending block modifications needing re-meshing.
     */
    public boolean isDirty() {
        return dirty;
    }

    public void setDirty(boolean dirty) {
        this.dirty = dirty;
    }

    public int getChunkX() {
        return chunkX;
    }

    public int getChunkZ() {
        return chunkZ;
    }
}
